const translations={kr:{navAbout:"소개",navInstall:"설치",navCode:"코드",navVscode:"VS Code",heroTitle:"자바스크립트의 직관적인 확장,<br>KRJS 런타임.",heroDesc:"Babel AST 기반으로 동작하며, 자연스러운 한국어 키워드로 코딩할 수 있는 모던 프로그래밍 언어 다이알렉트입니다.",btnNpm:"npm에서 설치",btnGh:"GitHub 레포지토리",c1Title:"아키텍처 개요",c1Desc:"단순 치환 방식이 아닌, 완전한 Babel AST(Abstract Syntax Tree) 파싱을 거쳐 안전하고 효율적인 순수 자바스크립트로 변환됩니다.",c1Li1:"안정적인 동기/비동기 흐름 제어",c1Li2:"전역 CLI 툴셋 <code>krnode</code> 탑재",c2Title:"패키지 설치",c2Desc:"Node.js 환경에서 글로벌 패키지를 설치하여 즉시 사용하실 수 있습니다.",secCodeTitle:"소스 코드 예시 (main.krjs)",secCodeDesc:"직관적인 한국어 키워드(<code>상수</code>, <code>함수</code>, <code>로그</code> 등)를 활용한 클린 코드 구조입니다.",secVsTitle:"VS Code 확장 프로그램",vsCardTitle:"asanaliopensource/krjs-vscode",vsCardDesc:"에디터 상단 패널의 <strong>Run</strong> 버튼 하나로 파일을 즉시 실행하고, 정교한 문법 강조(Syntax Highlighting)를 지원합니다.",vsLi1:"<code>.krjs</code> 파일 실시간 연동",vsLi2:"오픈소스 코드: ",footer:"&copy; 2026 KRJS Project. Open Source Software."},rus:{navAbout:"О проекте",navInstall:"Установка",navCode:"Код",navVscode:"VS Code",heroTitle:"Интуитивное расширение JavaScript,<br>рантайм KRJS.",heroDesc:"Работает на базе Babel AST, позволяя создавать код на чистом корейском синтаксисе с высокой производительностью.",btnNpm:"Установить из npm",btnGh:"Репозиторий GitHub",c1Title:"Обзор архитектуры",c1Desc:"Вместо простой замены текста используется компиляция через Babel AST в чистый, безопасный JavaScript.",c1Li1:"Надежное управление асинхронностью",c1Li2:"Встроенный глобальный CLI <code>krnode</code>",c2Title:"Установка пакета",c2Desc:"Установите глобальный пакет через Node.js для быстрого старта в любой директории.",secCodeTitle:"Пример кода (main.krjs)",secCodeDesc:"Используйте выразительные ключевые слова вроде <code>상수</code>, <code>함수</code> и <code>로그</code>.",secVsTitle:"Расширение для VS Code",vsCardTitle:"asanaliopensource/krjs-vscode",vsCardDesc:"Добавляет кнопку <strong>Run</strong> в верхнюю панель редактора для моментального запуска файлов <code>.krjs</code> и подсветку синтаксиса.",vsLi1:"Интеграция с файлами <code>.krjs</code>",vsLi2:"Исходный код: ",footer:"&copy; 2026 Проект KRJS. Открытый исходный код."},en:{navAbout:"About",navInstall:"Install",navCode:"Code",navVscode:"VS Code",heroTitle:"Intuitive JavaScript extension,<br>KRJS Runtime.",heroDesc:"Powered by Babel AST, allowing you to build software using expressive Korean keywords with native-like execution.",btnNpm:"Install via npm",btnGh:"GitHub Repository",c1Title:"Architecture Overview",c1Desc:"Instead of simple text replacement, it compiles securely into pure JavaScript via complete Babel AST parsing.",c1Li1:"Robust sync/async control flow",c1Li2:"Global CLI utility <code>krnode</code> included",c2Title:"Package Installation",c2Desc:"Quickly set up the global package in your Node.js environment to start building right away.",secCodeTitle:"Source Code Example (main.krjs)",secCodeDesc:"Write clean structures using keywords like <code>상수</code>, <code>함수</code>, and <code>로그</code>.",secVsTitle:"VS Code Extension",vsCardTitle:"asanaliopensource/krjs-vscode",vsCardDesc:"Adds a handy <strong>Run</strong> button to the editor header for instant <code>.krjs</code> execution and precise syntax highlighting.",vsLi1:"Seamless <code>.krjs</code> integration",vsLi2:"Open source: ",footer:"&copy; 2026 KRJS Project. Open Source Software."}};function getQueryLang(){const params=new URLSearchParams(window.location.search);const lang=params.get("krjs-lang");return translations[lang]?lang:"kr"}function changeLanguage(lang){document.getElementById("langSelect").value=lang;const t=translations[lang];document.getElementById("nav-about").innerText=t.navAbout;document.getElementById("nav-install").innerText=t.navInstall;document.getElementById("nav-code").innerText=t.navCode;document.getElementById("nav-vscode").innerText=t.navVscode;document.getElementById("hero-title").innerHTML=t.heroTitle;document.getElementById("hero-desc").innerText=t.heroDesc;document.getElementById("btn-npm").innerText=t.btnNpm;document.getElementById("btn-gh").innerText=t.btnGh;document.getElementById("c1-title").innerText=t.c1Title;document.getElementById("c1-desc").innerText=t.c1Desc;document.getElementById("c1-li1").innerText=t.c1Li1;document.getElementById("c1-li2").innerHTML=t.c1Li2;document.getElementById("c2-title").innerText=t.c2Title;document.getElementById("c2-desc").innerText=t.c2Desc;document.getElementById("sec-code-title").innerText=t.secCodeTitle;document.getElementById("sec-code-desc").innerHTML=t.secCodeDesc;document.getElementById("sec-vs-title").innerText=t.secVsTitle;document.getElementById("vs-card-title").innerText=t.vsCardTitle;document.getElementById("vs-card-desc").innerHTML=t.vsCardDesc;document.getElementById("vs-li1").innerHTML=t.vsLi1;const li2=document.getElementById("vs-li2");li2.innerHTML=t.vsLi2+'<a href="https://github.com/asanaliopensource/krjs-vscode" target="_blank" style="color: inherit; text-decoration: underline;">GitHub</a>';document.getElementById("footer-text").innerText=t.footer;document.documentElement.lang=lang}window.addEventListener("DOMContentLoaded",()=>{changeLanguage(getQueryLang())});
